('b1bb0057-6596-4c29-aace-3d1d933e1fd6', '21feff02-016d-46e2-bb9d-c27495133b1b', '131. óra: Az oszthatóságról tanultak összefoglalása', 'Év végi ismétlés: oszthatósági szabályok, prímek, lkkt és lnko.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "1566f05d-454a-451c-b00f-ffee17d97978", "text": "Osztható-e a 435 5-tel és 3-mal is (azaz 15-tel)?", "type": "true-false", "options": [{"id": "293efddc-a748-4ccb-af44-6162f79b5713", "text": "Igaz (5-re végződik és 4+3+5=12)", "isCorrect": true}, {"id": "4153b464-088a-4184-8dc0-09c3ac8f7d1e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cea0df5c-2809-4d3d-a102-6d38dcb5b4ab", "text": "Osztható-e a 612 4-gyel?", "type": "true-false", "options": [{"id": "dcdc3895-e45a-4a77-96f7-6ec7fd9f1d29", "text": "Igaz (12 osztható 4-gyel)", "isCorrect": true}, {"id": "ae58e750-c822-4680-bb91-a2f1ebc01bf2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fd02f6a5-269a-4820-ad69-90c32bad9889", "text": "Mennyi lkkt(6, 8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "e0d36671-f7a8-4b4e-b418-32c4dfc4d174", "text": "Mennyi lnko(12, 18)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "7694350c-68e5-4372-84a9-406a96d050c4", "text": "Melyik a legkisebbkétjegyű prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "30eb2567-bbb6-4a9e-ab2a-0f1cb441c939", "text": "A 2 az egyetlen páros prímszám.", "type": "true-false", "options": [{"id": "73971469-c996-4617-9c1a-19772adcb385", "text": "Igaz", "isCorrect": true}, {"id": "d4fd7202-d6f8-406d-a511-8afffdeb2bda", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6a161b08-4aa6-4301-bf6a-188349bcf4ff", "text": "Melyik szám osztható 9-cel?", "type": "multiple-choice", "options": [{"id": "5b95543c-43bd-412e-bb94-8f715e82c92d", "text": "819 (8+1+9=18)", "isCorrect": true}, {"id": "b06f03c2-7aeb-4e24-a309-e29af162301a", "text