('88137176-eb0b-4f64-b721-ea2552937ec8', '21feff02-016d-46e2-bb9d-c27495133b1b', '132. óra: A törtekről tanultak összefoglalása, vegyes feladatok', 'Év végi ismétlés: közönséges és tizedes törtek műveletei.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "aa853391-b373-4fd1-8cd2-1c671696bc7c", "text": "Mennyi 3/4 + 1/2? (3/4 + 2/4)", "type": "multiple-choice", "options": [{"id": "7a6a9356-932f-48a2-ba2d-3af1941a1193", "text": "5/4 (1 egész 1/4)", "isCorrect": true}, {"id": "cd669b21-e6b9-4030-beb9-8a6e109984b7", "text": "4/6", "isCorrect": false}, {"id": "b98ffdb7-20e7-4574-8bdd-cb3e5aa30b5e", "text": "4/4", "isCorrect": false}, {"id": "5a0396bb-fdaf-419c-aa56-986c04cb15b6", "text": "3/8", "isCorrect": false}], "timeLimit": 15}, {"id": "6c41f4d7-61d9-4f95-a1b0-97b628832398", "text": "Mennyi 2/3 * 3/5?", "type": "multiple-choice", "options": [{"id": "08c55ed0-84f8-4a9c-9a86-714cc1209f68", "text": "2/5", "isCorrect": true}, {"id": "be6285c8-6680-4a86-a50c-fc38d7a418ff", "text": "6/15", "isCorrect": false}, {"id": "35db9807-2094-45da-bc13-562623887b14", "text": "5/8", "isCorrect": false}, {"id": "57162c04-db6a-4f66-bec8-3a635c414656", "text": "6/8", "isCorrect": false}], "timeLimit": 15}, {"id": "66bfc3d5-42e8-40c9-b457-28980cf02573", "text": "Mennyi 1/2 : 1/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "0ea4e143-81d1-422d-803b-096c186445a3", "text": "Mennyi 2,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "cce2eb34-5cc9-4ec8-ae2c-8515e10e8e1f", "text": "Mennyi 4,8 : 0,6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "4ef362c8-edee-415f-bd49-ff91750d4d23", "text": "A 0,75 megegyezik a 3/4 törttel.", "type": "true-false", "options": [{"id": "ab53dbc7-2165-43e9-82fc-8eabe540a17b", "text": "Igaz", "isCorrect": true}, {"id": "2fd686e7-3a2f-4f14-8581-c2cd1efb494a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2d5c9