('3929d92a-91ee-4db6-8ddb-39ebf3f6adbc', '21feff02-016d-46e2-bb9d-c27495133b1b', '133. óra: A geometriai ismeretek összefoglalása, vegyes feladatok', 'Év végi ismétlés: szögek, alakzatok, tengelyes tükrözés.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "53b5e842-0dfe-473a-9d9d-306b9194a1f9", "text": "Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "488f1c30-6e87-45d1-97e2-712d6998573d", "text": "Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "7de7829a-f849-4684-9f2b-37c8b5afdbae", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "2e000fca-4e99-4e52-a4a9-8bcd483138a0", "text": "Ha a kör sugara 6 cm, mekkora az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "b579f241-ce28-4ca2-96b0-73f3f1e3e0dd", "text": "A tengelyes tükrözés távolságtartó transzformáció.", "type": "true-false", "options": [{"id": "6bc36d00-287a-4237-94d1-fc9872d99a00", "text": "Igaz", "isCorrect": true}, {"id": "058d2f3c-6f75-4b6d-9628-1bfdf0c475f9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f25e1407-4e50-42e4-815e-31da44450bf5", "text": "Hány fokos szöget zár be a szakaszfelező merőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "dc6d89b5-ec10-43e0-9330-5bc4a962ec9e", "text": "Milyen szög a 90°-os szög?", "type": "multiple-choice", "options": [{"id": "a2e66eb9-70f8-445f-8185-da38e497418b", "text": "Derékszög", "isCorrect": true}, {"id": "863b08e9-1010-40e2-bcbe-6d542eb9e046", "text": "Hegyesszög", "isCorrect": false}, {"id": "35ca4f76-7020-4dbf-8cd7-09844691015c", "text": "Tompaszög", "isCorrect": false}, {"id": "84c72b49-a325-4867-8732-d81664972ce7", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('9f1cb52d-b399-49ad-80e5-1f1e02476029', '21feff02-016d-46e2-bb9d-c27495133b1b', '134. óra: Arányosság, százalék, szöveges feladatok', 'Év végi ismétlés: egyenes arányosság, százalékszámítás, nyitott mondatok.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "46dbe933-ae36-45d0-ab7e-c63d5999bcbc", "text": "Ossz el 500 Ft-ot 2 : 3 arányban! Hány Ft a kisebbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "ef3bf597-f957-4e14-8ff0-e3ae16be28c6", "text": "Ha 3 kg narancs 1200 Ft, mennyibe kerül 7 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2800"}, {"id": "de1ef062-079e-4d99-8805-0a619f1140f4", "text": "Mennyi 4000 Ft-nak a 20%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "800"}, {"id": "72b6279e-bbf8-463a-a19e-bff487793d2f", "text": "Melyik szám teszi igazzá: 3 * x + 5 = 26? (21/3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "a44fa6a0-924d-4448-b476-e3fd7bdd17f6", "text": "Gondoltam egy számot, elosztottam 4-gyel, hozzáadtam 6-ot, 11-et kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "8e039ee7-f13a-48c1-adc5-69b04ff3563b", "text": "Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "7443e9c4-ef2e-4c43-9653-fba5023c7870", "text": "Igaz", "isCorrect": true}, {"id": "a7063795-295a-469e-ab0e-a65b57f9efa7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d34e8cef-11e7-4039-97e4-c476ecc6ccc7", "text": "Hány százalék felel meg a 4/5 törtszám teljes értékének?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "80"}]'::jsonb, true, NOW()),
('50d2bee6-927f-4fd8-b378-ad18fc3dae01', '21feff02-016d-46e2-bb9d-c27495133b1b', '135. óra: A hosszúság, a kerület, a terület és a térfogat fogalmával kapcsolatos feladatok', 'Év végi ismétlés: mérések, kerület, terület, felszín, térfogat.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "4802fc0e-d0bc-419d-901d-c206ced76855", "text": "Mennyi a 6 cm és 5 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "98aa4f58-d3bd-4116-95c5-ce7af551dc1c", "text": "Mennyi a 6 cm és 5 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "71ec1c54-ea40-44e4-b579-b126b023a93d", "text": "Mennyi a 4 cm élű kocka felszíne? (6 * 16)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "15a7413b-33a2-4e06-9db4-98bb28ee14d5", "text": "Mennyi a 4 cm élű kocka térfogata? (4 * 4 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "042b9ca6-18d4-4476-87fc-2ba34e3285ba", "text": "1 liter víz térfogata 1 dm³.", "type": "true-false", "options": [{"id": "d5d66675-6b33-4a2c-a158-79658e64f006", "text": "Igaz", "isCorrect": true}, {"id": "a7331b92-7412-4348-a1b8-730312e15e0f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c862bf94-0084-43e0-b1eb-3cf829bcd0d9", "text": "Hány cm³ 1 dm³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "57679e3b-35f9-440b-b207-7febcfaa32c0", "text": "Hány mm² 1 cm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}]'::jsonb, true, NOW()),
('02d32c35-fb67-4bd3-ba61-f0987cd9c88e', '21feff02-016d-46e2-bb9d-c27495133b1b', '136. óra: Az éves munka értékelése', 'Az 6. osztályos matematika törzsanyag sikeres teljesítésének záró értékelése.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "701d9b8c-09b6-42ac-b25b-5200fa08aca4", "text": "Mely főbb témaköröket dolgoztuk fel a 6. osztályos matematika tananyagban?", "type": "multiple-choice", "options": [{"id": "6a847ff5-09de-47c1-a4ec-72129dd8e7d0", "text": "Egész számok, oszthatóság, törtek, geometria, arány és százalék, kerület-terület-felszín-térfogat, statisztika, pénzügyek", "isCorrect": true}, {"id": "ed35f4e8-b269-4c5c-8900-3fbba0d24a1a", "text": "Kizárólag geometria", "isCorrect": false}, {"id": "1e567a14-0c3c-4aff-a0aa-bca17d3f6fe9", "text": "Kizárólag rajzolás", "isCorrect": false}, {"id": "48fbe178-522d-4eeb-9e84-5a6e77a6a9a6", "text": "Csak az 1. osztályos ismétlés", "isCorrect": false}], "timeLimit": 15}, {"id": "c421a0f0-cbf1-4391-a24f-4f09d0354caa", "text": "A szorgalmas felkészülés és a rendszerezett gyakorlás a matematikai tudás alapja.", "type": "true-false", "options": [{"id": "91a2e4c5-4649-4fcd-a2fc-e17c72b62ba5", "text": "Igaz", "isCorrect": true}, {"id": "4232da02-132f-4e07-85e5-6a883c81cb8b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "03756f00-80ee-486d-9476-78f23e7a793a", "text": "Hány órából állt a 6. osztályos teljes matematika tananyag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "136"}, {"id": "73a2917d-d258-4ed5-adcc-d080b2974891", "text": "A megszerzett matematikai tudás segít a mindennapi pénzügyekben és a döntéshozatalban.", "type": "true-false", "options": [{"id": "6fbb9abb-3594-4081-8dc5-c80b7aff6a13", "text": "Igaz", "isCorrect": true}, {"id": "c51bca85-97bc-43ad-9dd7-71a68da7e415", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2c2806d5-a6d6-4ac9-8050-4b567bf46889", "text": "Gratulálunk a 6. osztályos matematika tananyag sikeres teljesítéséhez!", "type": "true-false", "options": [{"id": "9a1ce2f4-5f5d-4810-8d11-1e04a8b07aaa", "text": "Igaz", "isCorrect": true}, {"id": "c6e14181-03c5-4cf3-bb14-68253d47c641", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "336233ad-0512-4794-89e3-82232e075af5", "text": "A 7. osztályban az itt megszerzett alapokra (pl. oszthatóság, törtek, százalék, geometria) építünk tovább.", "type": "true-false", "options": [{"id": "d6538c1a-12c1-40d2-8132-a9e9f36cc5fc", "text": "Igaz", "isCorrect": true}, {"id": "351099d8-73a9-4e45-9a94-5fa0f691b583", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e86177da-396e-4420-b7d0-ce56614038c0", "text": "Melyik volt a kedvenc témaköröd ebben a tanévben?", "type": "multiple-choice", "options": [{"id": "62627052-c350-49f0-aa05-dffd5534adb1", "text": "Mindegyik témakör hasznos és érdekes volt!", "isCorrect": true}, {"id": "be76c4ae-a704-4676-864e-c8ce602b5dc1", "text": "Egész számok és oszthatóság", "isCorrect": false}, {"id": "aa4ef2f0-6fbb-489d-b032-711835e0285b", "text": "Geometria és tengelyes tükrözés", "isCorrect": false}, {"id": "030c0947-92ba-432e-8a9d-f211a4b0bd61", "text": "Arányosság és százalékszámítás", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;